export default function MonthlySales(props){
  //static demoUrl = 'https://codesandbox.io/s/simple-line-chart-kec3v';

  var DATA=[]
  props.dat.datasets[0].data.map((e,index)=>{DATA.push({name:props.dat.labels[index],"tnd":e})})
  
    return (
      <ResponsiveContainer width="100%" height="90%">
        <Title>Monthly Revenues</Title>
        <LineChart
          width={500}
          height={300}
          data={DATA}
          margin={{
            top: 5,
            right: 30,
            left: 20,
            bottom: 5,
          }}
        >
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="name" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="tnd" stroke="#8884d8" activeDot={{ r: 8 }} />
          {/* <Line type="monotone" dataKey="uv" stroke="#82ca9d" /> */}
        </LineChart>
      </ResponsiveContainer>
    )
}
